"""Synthetic lasts with closed-form signed distance, built as build123d solids.

Everything here is generated by code (plan 1.4: no real assets). Each :class:`SyntheticLast`
carries the solid (so the full STEP -> mesh path can be exercised) and exact references:

* ``sdf(p)``: exact signed distance of the solid, negative inside;
* ``footprint_sdf(xy)``: exact 2D signed distance of the projection onto the XY plane;
* ``height(xy)``: the lowest z of the solid above each XY, nearest-boundary extrapolation
  outside the footprint (plan M0.3);
* ``medial_distance(p)``: a lower bound on the distance of ``p`` to the shape's medial axis
  (``inf`` outside the shape), i.e. to the places where the SDF has a kink;
* ``footprint_medial_distance(xy)``: the same for the 2D footprint SDF.

Variants
--------
``rounded_last``  box 120 x 50 x 40 with all edges rounded by 10 mm, bottom at z = 0.
``hemisphere_last``  disc of radius 50 over a lower hemisphere (R = 50) under a 30 mm tall
    cylinder; its bottom has an infinite slope at the footprint outline.
``heel_rise_last``  the rounded box tilted about Y so that the heel end (x = 0) of the
    bottom face is 30 mm above the toe end (M0.8 uses it).
"""

from __future__ import annotations

import math
from collections.abc import Callable
from dataclasses import dataclass

import numpy as np
from scipy import ndimage

R_HEMI = 50.0
H_HEMI = 30.0


@dataclass(frozen=True)
class SyntheticLast:
    name: str
    shape: object
    bbox_min: tuple[float, float, float]
    bbox_max: tuple[float, float, float]
    sdf: Callable[[np.ndarray], np.ndarray]
    footprint_sdf: Callable[[np.ndarray], np.ndarray]
    height: Callable[[np.ndarray], np.ndarray]
    medial_distance: Callable[[np.ndarray], np.ndarray]
    footprint_medial_distance: Callable[[np.ndarray], np.ndarray]


# ------------------------------------------------------------------ closed-form helpers


def box_sdf(p: np.ndarray, center, half) -> np.ndarray:
    """Exact signed distance of an axis-aligned box (works for 2D and 3D points)."""
    q = np.abs(p - np.asarray(center, dtype=np.float64)) - np.asarray(half, dtype=np.float64)
    return np.linalg.norm(np.maximum(q, 0.0), axis=1) + np.minimum(q.max(axis=1), 0.0)


def _box_medial_distance(p: np.ndarray, half) -> np.ndarray:
    """Lower bound of the distance to the medial axis of a box centred at the origin."""
    hh = np.asarray(half, dtype=np.float64)
    # distances to the six faces (positive inside); face order +x -x +y -y +z -z
    a = np.stack(
        [
            hh[0] - p[:, 0],
            hh[0] + p[:, 0],
            hh[1] - p[:, 1],
            hh[1] + p[:, 1],
            hh[2] - p[:, 2],
            hh[2] + p[:, 2],
        ],
        axis=1,
    )
    axis_of = np.array([0, 0, 1, 1, 2, 2])
    order = np.argsort(a, axis=1)
    i1, i2 = order[:, 0], order[:, 1]
    m1 = np.take_along_axis(a, i1[:, None], axis=1)[:, 0]
    m2 = np.take_along_axis(a, i2[:, None], axis=1)[:, 0]
    opposite = axis_of[i1] == axis_of[i2]
    tie = (m2 - m1) / np.where(opposite, 2.0, math.sqrt(2.0))
    out_dist = np.linalg.norm(np.maximum(np.abs(p) - hh, 0.0), axis=1)
    inside = np.all(np.abs(p) <= hh, axis=1)
    return np.where(inside, tie, out_dist)


def _rect_medial_distance(p: np.ndarray, centre, half) -> np.ndarray:
    """Lower bound of the distance to the skeleton of a rectangle (2D box)."""
    rel = p - np.asarray(centre, dtype=np.float64)
    hh = np.asarray(half, dtype=np.float64)
    a = np.stack([hh[0] - rel[:, 0], hh[0] + rel[:, 0], hh[1] - rel[:, 1], hh[1] + rel[:, 1]], 1)
    axis_of = np.array([0, 0, 1, 1])
    order = np.argsort(a, axis=1)
    i1, i2 = order[:, 0], order[:, 1]
    m1 = np.take_along_axis(a, i1[:, None], axis=1)[:, 0]
    m2 = np.take_along_axis(a, i2[:, None], axis=1)[:, 0]
    tie = (m2 - m1) / np.where(axis_of[i1] == axis_of[i2], 2.0, math.sqrt(2.0))
    out = np.linalg.norm(np.maximum(np.abs(rel) - hh, 0.0), axis=1)
    return np.where(np.all(np.abs(rel) <= hh, axis=1), tie, out)


def lower_envelope(sdf: Callable[[np.ndarray], np.ndarray], xy: np.ndarray, z_lo, z_hi, dz=0.1):
    """Lowest z with sdf = 0 above each xy (first outside -> inside crossing), NaN if none."""
    xy = np.asarray(xy, dtype=np.float64)
    zs = np.arange(z_lo, z_hi + dz, dz)
    out = np.full(len(xy), np.nan)
    step = 2000
    for start in range(0, len(xy), step):
        chunk = xy[start : start + step]
        m = len(chunk)
        pts = np.empty((m * len(zs), 3))
        pts[:, :2] = np.repeat(chunk, len(zs), axis=0)
        pts[:, 2] = np.tile(zs, m)
        inside = (sdf(pts) < 0).reshape(m, len(zs))
        first = np.argmax(inside, axis=1)
        rows = np.flatnonzero(inside.any(axis=1) & (first > 0))
        lo = zs[first[rows] - 1]
        hi = zs[first[rows]]
        for _ in range(45):
            mid = 0.5 * (lo + hi)
            v = sdf(np.column_stack([chunk[rows], mid]))
            neg = v < 0
            hi = np.where(neg, mid, hi)
            lo = np.where(neg, lo, mid)
        out[start + rows] = hi
    return out


# ------------------------------------------------------------------ rounded box (and heel)


def _rounded_box_solid(length, width, height, radius):
    from build123d import Box, fillet

    return fillet(Box(length, width, height).edges(), radius)


def _rounded_box_sdf(p: np.ndarray, half, radius) -> np.ndarray:
    # exact on both sides: the rounded box is the inner box dilated by a ball
    return box_sdf(p, (0.0, 0.0, 0.0), np.asarray(half) - radius) - radius


def rounded_last(length=120.0, width=50.0, height=40.0, radius=10.0) -> SyntheticLast:
    """Rounded box with x in [0, length], y centred, z in [0, height]."""
    from build123d import Pos

    half = np.array([length, width, height]) / 2.0
    centre = half * np.array([1.0, 0.0, 1.0])
    solid = Pos(*centre) * _rounded_box_solid(length, width, height, radius)
    inner = half - radius

    def sdf(p):
        return _rounded_box_sdf(p - centre, half, radius)

    def footprint_sdf(xy):
        return box_sdf(xy, centre[:2], inner[:2]) - radius

    def height_fn(xy):
        # depth inside the outline selects the point on the bottom fillet; outside: edge value
        depth = np.clip(-footprint_sdf(xy), 0.0, radius)
        return radius - np.sqrt(np.maximum(radius**2 - (radius - depth) ** 2, 0.0))

    def medial(p):
        return _box_medial_distance(p - centre, inner)

    def fp_medial(xy):
        return _rect_medial_distance(xy, centre[:2], inner[:2])

    return SyntheticLast(
        "rounded",
        solid,
        (0.0, -width / 2, 0.0),
        (length, width / 2, height),
        sdf,
        footprint_sdf,
        height_fn,
        medial,
        fp_medial,
    )


def heel_rise_last(
    length=120.0, width=50.0, height=40.0, radius=10.0, heel_rise=30.0
) -> SyntheticLast:
    """The rounded box tilted about Y: the bottom face rises ``heel_rise`` mm toward x = 0."""
    from build123d import Axis, Pos

    theta = math.atan2(heel_rise, length - 2 * radius)
    c, s = math.cos(theta), math.sin(theta)
    rot = np.array([[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]])  # about +Y by theta
    half = np.array([length, width, height]) / 2.0
    inner = half - radius
    base = _rounded_box_solid(length, width, height, radius).rotate(Axis.Y, math.degrees(theta))
    corners = np.array(
        [
            [sx * inner[0], sy * inner[1], sz * inner[2]]
            for sx in (-1, 1)
            for sy in (-1, 1)
            for sz in (-1, 1)
        ]
    )
    rc = corners @ rot.T
    lo = rc.min(axis=0) - radius
    hi = rc.max(axis=0) + radius
    shift = np.array([-lo[0], 0.0, -lo[2]])
    solid = Pos(*shift) * base

    def to_local(p):
        return (p - shift) @ rot  # x = R^T (p - shift)

    def sdf(p):
        return _rounded_box_sdf(to_local(p), half, radius)

    # A box rotated about Y projects to a rectangle in XY; the rounding adds a disc.
    fp_half = np.array([abs(c) * inner[0] + abs(s) * inner[2], inner[1]])
    fp_centre = np.array([shift[0], 0.0])

    def footprint_sdf(xy):
        return box_sdf(xy, fp_centre, fp_half) - radius

    zmax = float(hi[2] + shift[2])

    def height_fn(xy):
        xy = np.asarray(xy, dtype=np.float64)
        q = xy.copy()
        out = footprint_sdf(xy) > 0
        if out.any():  # nearest outline point (just inside, the envelope is continuous)
            ctr = np.clip(xy[out], fp_centre - fp_half, fp_centre + fp_half)
            v = xy[out] - ctr
            q[out] = ctr + v / np.linalg.norm(v, axis=1, keepdims=True) * (radius - 1e-7)
        return lower_envelope(sdf, q, -1.0, zmax + 1.0, 0.1)

    def medial(p):
        return _box_medial_distance(to_local(p), inner)

    def fp_medial(xy):
        return _rect_medial_distance(xy, fp_centre, fp_half)

    return SyntheticLast(
        "heel_rise",
        solid,
        (0.0, -width / 2, 0.0),
        (float(hi[0] - lo[0]), width / 2, float(hi[2] - lo[2])),
        sdf,
        footprint_sdf,
        height_fn,
        medial,
        fp_medial,
    )


# ------------------------------------------------------------------ hemisphere bowl


def _hemi_profile(rho: np.ndarray, z: np.ndarray):
    """Exact signed distance, nearest-piece id and inside flag in the (rho >= 0, z) plane."""
    r = np.hypot(rho, z)
    d_top = np.hypot(rho - np.clip(rho, 0.0, R_HEMI), z - H_HEMI)  # z = H, rho in [0, R]
    d_wall = np.hypot(rho - R_HEMI, z - np.clip(z, 0.0, H_HEMI))  # rho = R, z in [0, H]
    d_arc = np.where(z <= 0.0, np.abs(r - R_HEMI), np.hypot(rho - R_HEMI, z))  # lower arc
    pieces = np.stack([d_top, d_wall, d_arc])
    dist = pieces.min(axis=0)
    inside = ((rho <= R_HEMI) & (z >= 0.0) & (z <= H_HEMI)) | ((z < 0.0) & (r < R_HEMI))
    return np.where(inside, -dist, dist), pieces.argmin(axis=0), inside


def hemisphere_last() -> SyntheticLast:
    from build123d import Box, Cylinder, Pos, Sphere

    lower = Sphere(R_HEMI) & (Pos(0, 0, -100) * Box(200, 200, 200))
    solid = (Pos(0, 0, H_HEMI / 2) * Cylinder(R_HEMI, H_HEMI)) + lower
    solids = solid.solids()
    shape = solids[0] if len(solids) == 1 else solid

    def sdf(p):
        return _hemi_profile(np.hypot(p[:, 0], p[:, 1]), p[:, 2])[0]

    def footprint_sdf(xy):
        return np.hypot(xy[:, 0], xy[:, 1]) - R_HEMI

    def height_fn(xy):
        rho = np.minimum(np.hypot(xy[:, 0], xy[:, 1]), R_HEMI)
        return -np.sqrt(np.maximum(R_HEMI**2 - rho**2, 0.0))

    # Medial axis = ties between the three boundary pieces, located on a profile grid.
    step = 0.1
    rr = np.arange(0.0, R_HEMI + step, step)
    zz = np.arange(-R_HEMI, H_HEMI + step, step)
    gr, gz = np.meshgrid(rr, zz, indexing="ij")
    _, pid, ins = _hemi_profile(gr, gz)
    tie = np.zeros_like(ins)
    tie[:-1, :] |= (pid[:-1, :] != pid[1:, :]) & ins[:-1, :] & ins[1:, :]
    tie[:, :-1] |= (pid[:, :-1] != pid[:, 1:]) & ins[:, :-1] & ins[:, 1:]
    dist_to_medial = ndimage.distance_transform_edt(~tie) * step

    def medial(p):
        rho = np.hypot(p[:, 0], p[:, 1])
        ir = np.clip(np.rint(rho / step).astype(int), 0, len(rr) - 1)
        iz = np.clip(np.rint((p[:, 2] - zz[0]) / step).astype(int), 0, len(zz) - 1)
        inside = _hemi_profile(rho, p[:, 2])[2]
        return np.where(inside, dist_to_medial[ir, iz], np.inf)

    def fp_medial(xy):
        return np.hypot(xy[:, 0], xy[:, 1])  # a disc's skeleton is its centre

    return SyntheticLast(
        "hemisphere",
        shape,
        (-R_HEMI, -R_HEMI, -R_HEMI),
        (R_HEMI, R_HEMI, H_HEMI),
        sdf,
        footprint_sdf,
        height_fn,
        medial,
        fp_medial,
    )


def hemisphere_surface_distance(p: np.ndarray, offset: float = 0.0) -> np.ndarray:
    """Exact signed distance to the open surface z = h(x, y) + offset of the hemisphere last.

    h = -sqrt(R^2 - rho^2) inside the footprint and 0 outside (edge value): a revolved arc
    plus the plane z = offset beyond rho = R. Negative below the surface.
    """
    rho = np.hypot(p[:, 0], p[:, 1])
    z = p[:, 2] - offset
    r = np.hypot(rho, z)
    d_arc = np.where(z <= 0.0, np.abs(r - R_HEMI), np.hypot(rho - R_HEMI, z))
    d_plane = np.where(rho >= R_HEMI, np.abs(z), np.hypot(R_HEMI - rho, z))
    dist = np.minimum(d_arc, d_plane)
    below = (z < 0.0) & ((rho >= R_HEMI) | (r > R_HEMI))
    return np.where(below, -dist, dist)


ALL_LASTS = {
    "rounded": rounded_last,
    "hemisphere": hemisphere_last,
    "heel_rise": heel_rise_last,
}
